class GLMTrainer:
    def __init__(self):
        self.model = glm(alpha=1e-6, max_iter=500)

    def train(self, X, y, exposure=None):
        if exposure is not None:
            self.model.fit(X, y, sample_weight=exposure)
        else:
            self.model.fit(X, y)

    def predict(self, X):
        return self.model.predict(X)

    def save(self, path):
        joblib.dump(self.model, path)
